#version 300 es
precision highp float;

// VisualSynth uniforms
uniform float uTime;
uniform float uFrame;
uniform float uFps;
uniform float uRms;

// Audio uniforms
uniform float audioLow;      // bass
uniform float audioLowSmooth; // bass_att
uniform float audioMid;      // mid
uniform float audioMidSmooth; // mid_att
uniform float audioHigh;     // treb
uniform float audioHighSmooth; // treb_att

// Screen uniforms
uniform float uAspectX;
uniform float uAspectY;
uniform vec2 uAspect;
uniform vec2 uTexSize;

// Random values
uniform vec2 uRandomPreset;
uniform vec2 uRandomFrame;

// Input from vertex shader
in vec2 vUv;
in vec2 vUvOriginal;
in float vRadius;
in float vAngle;

// Output
out vec4 fragColor;

// Textures
uniform sampler2D sampler_main;
uniform sampler2D sampler_noise_lq;
uniform sampler2D sampler_noise_mq;
uniform sampler2D sampler_noise_hq;
uniform sampler2D sampler_blur1;
uniform sampler2D sampler_blur2;
uniform sampler2D sampler_blur3;

// Helper functions
float clamp01(float x) { return clamp(x, 0.0, 1.0); }
vec2 clamp01(vec2 x) { return clamp(x, vec2(0.0), vec2(1.0)); }
vec3 clamp01(vec3 x) { return clamp(x, vec3(0.0), vec3(1.0)); }
vec4 clamp01(vec4 x) { return clamp(x, vec4(0.0), vec4(1.0)); }

// Texture helper functions
vec3 GetPixel(vec2 uv) { return texture(sampler_main, uv).xyz; }
vec3 GetBlur1(vec2 uv) { return texture(sampler_blur1, uv).xyz; }
vec3 GetBlur2(vec2 uv) { return texture(sampler_blur2, uv).xyz; }
vec3 GetBlur3(vec2 uv) { return texture(sampler_blur3, uv).xyz; }

vec4 textureMirror(sampler2D tex, vec2 c){
vec2 cf = fract(c);
return texture(tex,mix(cf,1.-cf,mod_conv(floor(c),2.)));
}
float amp(vec2 p){
return smoothstep(1,8.,abs(p.x));
}
float pow512(float a){
a*=a;//^2
a*=a;//^4
a*=a;//^8
a*=a;//^16
a*=a;//^32
a*=a;//^64
a*=a;//^128
a*=a;//^256
return a*a;
}
float pow1d5(float a){
return a*sqrt(a);
}
float hash21(vec2 co){
return fract(sin(dot(co.xy,vec2(1.9898,7.233)))*45758.5433);
}
float hash(vec2 uv_conv){
float a = amp(uv_conv);
#ifdef wave_thing
float w = a>0.?(1.-.4*pow512(.51+.49*sin((.02*(uv_conv.y+.5*uv_conv.x)-jTime)*2.))):0.;
#else
float w=1.;
#endif
return (a>0 ? a*pow1d5(hash21(uv_conv))*w:0.)-(textureMirror(iChannel0,vec2((uv_conv.x*29.uv_conv.y)*.03125,1.)).x)*audio_vibration_amplitude;
}
float edgeMin(float dx_c,vec2 da, vec2 db,vec2 uv_conv){
uv_conv.x+=5.;
vec3 c = fract((round(vec3(uv_conv,uv_conv.x+uv_conv.y)))*(vec3(0,1,2)+0.61803398875));
float a1 = 1;
float a2 = textureMirror(iChannel0,vec2(c.x,0.)).x>.6?.15:1.;
float a3 = textureMirror(iChannel0,vec2(c.z,0.)).x>.6?.15:1.;
return min(min((1-dx_c)*db.y*a3,da.x*a2),da.y*a1);
}
vec2 trinoise(vec2 uv_conv){
const float sq = sqrt(3./2.);
uv_conv.x *= sq;
uv_conv.y -= .5*uv_conv.x;
vec2 d = fract(uv_conv);
uv_conv -= d;
bool c = dot(d,vec2(1, 1))>1.;
vec2 dd = 1.-d;
vec2 da = c?dd:d,db = c?d:dd;
float nn = hash(uv_conv+float(c));
float n2 = hash(uv_conv+vec2(1,0));
float n3 = hash(uv_conv+vec2(0,1));
float nmid = mix(n2,n3,d.y);
float ns = mix(nn,c?n2:n3,da.y);
float dx = da.x/db.y;
return vec2(mix(ns,nmid,dx),edgeMin(dx,da, db,uv_conv+d));
}
vec2 map(vec3 p){
vec2 n = trinoise(p.xz);
return vec2(p.y-2.*n.x,n.y);
}
vec3 grad(vec3 p){
const vec2 e = vec2(.005,0);
float a =map(p).x;
return vec3(map(p+e.xyy).x-a
,map(p+e.yxy).x-a
,map(p+e.yyx).x-a)/e.x;
}
vec2 intersect(vec3 ro,vec3 rd){
float d=0,h=0;
vec2 ret_c=0;
for(int i = 0;i<120;i++){ //look nice with 50 iterations
vec3 p = ro+d*rd;
vec2 s = map(p);
h = s.x;
d+= h*.5;
if(abs(h)<0.005*d) {
 ret_c = vec2(d,s.y);
} else {
 // CONV: break unsupported, see Milkwave manual
 if(d>150.|| p.y>2.) {
  i=500;
 }
 else {
  ret_c = vec2(-1, -1);
 }
}
} // end for
return ret_c;
}
void addsun(vec3 rd,vec3 ld,inout vec3 col){
float sun = smoothstep(.21,.2,distance(rd,ld));
if(sun>0.){
float yd = (rd.y-ld.y);
float a = sin(3.1*exp(-(yd)*14.));
sun *= smoothstep(-.8,0,a);
col = mix(col,vec3(1.,.8,.4)*.75,sun);
}
}
float starnoise(vec3 rd){
float c = 0.;
vec3 p = normalize(rd)*300.;
for (float i=0.;i<4.;i++)
{
vec3 q = fract(p)-.5;
vec3 id = floor(p);
float c2 = smoothstep(.5,0.,length(q));
c2 *= step(hash21(id.xz/id.y),.06-i*i*0.005);
c += c2;
p = multiply(p*.6+.5*p, transpose(mat3(3./5.,0,4./5.,0,1,0,-4./5.,0,3./5.)));
}
c*=c;
float g = dot(sin(rd*10.512),cos(rd.yzx*10.512));
c*=smoothstep(-3.14,-.9,g)*.5+.5*smoothstep(-.3,1.,g);
return c*c;
}
vec3 gsky(vec3 rd,vec3 ld,bool mask){
float haze = exp2(-5.*(abs(rd.y)-.2*dot(rd,ld)));
float st = mask?(starnoise(rd))*(1.-min(haze,1.)):0.;
vec3 back = vec3(.4,.1,.7)*(1.-.5*textureMirror(iChannel0,vec2(.5+.05*rd.x/rd.y,0.)).x
*exp2(-.1*abs(length(rd.xz)/rd.y))
*max(sign(rd.y),0.));
#ifdef city
float x = round(rd.x*30.);
float h = hash21(vec2(x-166.,x-166.));
bool building = (h*h*.125*exp2(-x*x*x*x*.0025)>rd.y);
if(mask && building)
back*=0.,haze=.8, mask=mask && !building;
#endif
vec3 col=clamp(mix(back,vec3(.7,.1,.4),haze)+st,0.,1.);
if(mask) addsun(rd,ld,col);
return col;
}

void main() {
  vec4 ret = vec4(0.0);
  vec2 uv = vUv;
  vec2 uv_orig = vUvOriginal;
  float rad = vRadius;
  float ang = vAngle;
  // stduhpf + IkeC - another synthwave sunset thing / https://www.shadertoy.com/view/tsScRK
// Transpiled to HLSL using Milkwave
#define iChannel0 sampler_noise_lq
#define tx (sin(uTime)*0.5+1)
float mod_conv(float x, float y) { return x - y * floor(x / y); }
vec2 mod_conv(vec2 x, vec2 y) { return x - y * floor(x / y); }
vec3 mod_conv(vec3 x, vec3 y) { return x - y * floor(x / y); }
vec4 mod_conv(vec4 x, vec4 y) { return x - y * floor(x / y); }
#define speed 8
#define wave_thing
//#define city 1
#define disable_sound_texture_sampling
#ifndef disable_sound_texture_sampling
#undef speed
#define speed 5.
#endif
#define audio_vibration_amplitude .125
float jTime;
#ifdef disable_sound_texture_sampling
#define textureMirror(a, b) vec4(0,0,0,0)
#else
#endif
vec4 fragColor = 0;
// CONV: Center on screen, then try some uAspect correction
uv = (uv*2) - 1;
uv *= uAspect.xy;
// CONV: Adjust this to flip the output (±uv.x, ±uv.y)
uv = vec2(uv.x, -uv.y);
vec2 fragCoord  = uv;


#ifdef AA
for(float x = 0.;x<1.;x+=1./float(AA)){
for(float y = 0.;y<1.;y+=1./float(AA)){
#else
const float AA=1.,x=0.,y=0.;
#endif

//uv = (2.*(fragCoord+vec2(x,y))-uv.xy)/uv.y;

const float shutter_speed = .25; // for motion blur

//float dt = fract(texture(iChannel0,float(AA)*(fragCoord+vec2(x,y))/uv.xy).r+uTime)*shutter_speed;

float dt = fract(hash21(float(AA)*(fragCoord+vec2(x,y)))+uTime)*shutter_speed;

jTime = uTime;

float fx = sin(uTime*0.3)*0.3;
#ifdef bass_smooth
float fy = 0.7+0.2*bass_smooth;
#else
float fy = sin(uTime*0.3)*0.3+1.1;
#endif
float fz = (-20000.+jTime*speed);
vec3 ro = vec3(fx,fy,fz);

#ifdef stereo
ro+=stereo*vec3(.2*(float(uv.x>0.)-.5),0.,0.);
const float de = .9;
uv.x=uv.x+.5*(uv.x>0.?-de:de);
uv*=2.;
#endif
float dis = 1.2;
vec3 rd = normalize(vec3(uv,dis));
//vec3 rd = normalize(vec3(uv,sqrt(1.-dot(uv,uv))));

vec2 i = intersect(ro,rd);
float d = i.x;
float sunheight = .16;
float f1 = sunheight+.05*0.35*cos(jTime*0.1);
vec3 ld = normalize(vec3(0,f1,0.7));
vec3 fog = d>0.?exp2(-d*vec3(.14,.1,.28)):vec3(0,0,0);
vec3 sky = gsky(rd,ld,d<0.);

vec3 p = ro+d*rd;
vec3 n = normalize(grad(p));

float diff = dot(n,ld)+.1*n.y;
vec3 col = vec3(.1,.11,.18)*diff;

vec3 rfd = reflect(rd,n);
vec3 rfcol = gsky(rfd,ld,true);

// floor
//col = mix(col,rfcol,.05+.95*pow(max(1.+dot(rd,n),0.),5.));

float shiny = 0.88;
col = mix(col,rfcol,.05+.95*pow(max(1.+dot(rd,n),shiny),5.));

#ifdef VAPORWAVE
col = mix(col,vec3(.4,.5,1.),smoothstep(.05,.0,i.y));
col = mix(sky,col,fog);
col = sqrt(col);
#else
col = mix(col,vec3(.8,.1,.92),smoothstep(.05,0,i.y));
col = mix(sky,col,fog);
//no gamma for that old cg look
#endif

if(d<0.) d=1e6;
d=min(d,10.);

fragColor += vec4(clamp(col,0,1),d<0. ? 0 : 0.1+exp2(-d));

#ifdef AA
fragColor/=float(AA*AA);
}}
#endif
ret = fragColor;
  fragColor = ret;
}
